+public class TestByteBufferArray {
+
+  @Test
+  public void testAsSubBufferWhenEndOffsetLandInLastBuffer() throws Exception {
+    int capacity = 4 * 1024 * 1024;
+    ByteBufferArray array = new ByteBufferArray(capacity, false);
